def nthUglyNumber(n):
    i = 0
    Ist = [1]
    seen = {1}

    while i < n - 1:
        ugly = Ist[i]
        for factor in [2, 3, 5]:
            new = ugly * factor
            if new not in seen:
                seen.add(new)
                Ist.append(new)
        i += 1

    return Ist[n - 1]
